import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { catchError } from 'rxjs/operators';
import { of, EMPTY } from 'rxjs';
import { HeaderMenus } from 'src/app/Models/header-menus.dto';
import { PostDTO } from 'src/app/Models/post.dto';
import { HeaderMenusService } from 'src/app/Services/header-menus.service';
import { LocalStorageService } from 'src/app/Services/local-storage.service';
import { PostService } from 'src/app/Services/post.service';
import { SharedService } from 'src/app/Services/shared.service';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss'],
})
export class HomeComponent {
  posts!: PostDTO[];
  showButtons: boolean;
  constructor(
    private postService: PostService,
    private localStorageService: LocalStorageService,
    private sharedService: SharedService,
    private router: Router,
    private headerMenusService: HeaderMenusService,
  ) {
    this.showButtons = false;
    this.loadPosts();
  }

  ngOnInit(): void {
    this.headerMenusService.headerManagement.subscribe(
      (headerInfo: HeaderMenus) => {
        if (headerInfo) {
          this.showButtons = headerInfo.showAuthSection;
        }
      },
    );
  }
  private loadPosts(): void {
    // TODO 2
    let errorResponse: any;

    const userId = this.localStorageService.get('user_id');
    if (userId) {
      this.showButtons = true;
    }

    this.postService.getPosts().pipe(
      catchError((error: any) => {
        this.sharedService.errorLog(error.error);
        return of([]);
      })
    ).subscribe((posts: PostDTO[]) => {
      this.posts = posts;
    });
  }

  like(postId: string):void {
    this.postService.likePost(postId).pipe(
      catchError((error: any) => {
        this.sharedService.errorLog(error.error);
        return EMPTY;
      }))
      .subscribe(() => {
        this.loadPosts();
      });
  }

  dislike(postId: string): void {
    this.postService.dislikePost(postId).pipe(
      catchError((error: any) => {
        this.sharedService.errorLog(error.error);
        return EMPTY;
      })
    ).subscribe(() => {
      this.loadPosts();
    });
  }
}
<p>List All posts</p>

<div style="text-align: center">
  <div *ngFor="let post of posts" class="card">
    <div class="container">
      <div>
        <span
          *ngFor="let category of post.categories"
          class="badge"
          [ngStyle]="{ 'background-color': category.css_color }"
        >
          {{ category.title }}
        </span>
      </div>
    </div>

    <h4>
      <b>Title: {{ post.title }}</b>
    </h4>
    <p>Description: {{ post.description }}</p>
    <p>Likes: {{ post.num_likes }}</p>
    <p>Dislikes: {{ post.num_dislikes }}</p>
    <p>Publication date: {{ post.publication_date | formatDate: 3 }}</p>
    <p>Published by: {{ post.userAlias }}</p>

    <div *ngIf="showButtons">
      <button (click)="like(post.postId)">Like</button>
      <button (click)="dislike(post.postId)">Dislike</button>
    </div>
  </div>
</div>
